  "knowledge": "Whale Fan",
  "description": "A fan who demonstrates extremely high in-session spending, representing a top-tier financial contributor.",
  "definition": "A fan is classified as a Whale Fan if their Fan Monetization Index (FMI) is greater than 20."
}

